G = load()

def find_shapes(grid, color):
    """Find connected components of a given color"""
    shapes = []
    visited = set()
    h, w = len(grid), len(grid[0])

    def dfs(i, j):
        if i < 0 or i >= h or j < 0 or j >= w or grid[i][j] != color or (i,j) in visited:
            return []
        visited.add((i,j))
        res = [(i,j)]
        res.extend(dfs(i+1, j))
        res.extend(dfs(i-1, j))
        res.extend(dfs(i, j+1))
        res.extend(dfs(i, j-1))
        return res

    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and (i,j) not in visited:
                shape = sorted(dfs(i,j))
                if shape:
                    shapes.append(shape)
    return shapes

