# Let me analyze by color and see if there's a relationship between original min/max row/col
# and destination

def analyze_by_color(grid_in, grid_out, color):
    print(f"\n=== Color {color} ===")

    def get_components(color, grid):
        visited = set()
        h, w = len(grid), len(grid[0])
        comps = []

        def dfs(i, j):
            stack = [(i,j)]
            result = []
            while stack:
                ii, jj = stack.pop()
                if ii < 0 or ii >= h or jj < 0 or jj >= w or grid[ii][jj] != color or (ii,jj) in visited:
                    continue
                visited.add((ii,jj))
                result.append((ii,jj))
                stack.extend([(ii+1, jj), (ii-1, jj), (ii, jj+1), (ii, jj-1)])
            return sorted(result)

        for i in range(h):
            for j in range(w):
                if grid[i][j] == color and (i,j) not in visited:
                    comp = dfs(i,j)
                    if comp:
                        mins = [min(r,c) for r,c in comp]
                        maxs = [max(r,c) for r,c in comp]
                        bbox = (min(mins), max(mins), min(maxs), max(maxs))  # (rmin, rmax, cmin, cmax)
                        comps.append({
                            'cells': comp,
                            'size': len(comp),
                            'bbox': bbox,
                            'centroid': (sum(r for r,c in comp)//len(comp), sum(c for r,c in comp)//len(comp))
                        })
        return comps

    in_comps = get_components(color, grid_in)
    out_comps = get_components(color, grid_out)

    print(f"Input components:")
    for idx, c in enumerate(in_comps):
        print(f"  {idx}: size={c['size']}, bbox={c['bbox']}")

    print(f"Output components:")
    for idx, c in enumerate(out_comps):
        print(f"  {idx}: size={c['size']}, bbox={c['bbox']}")

    # Try to match by size
    print("\nMapping by size:")
    size_to_in = {c['size']: i for i, c in enumerate(in_comps)}
    size_to_out = {c['size']: i for i, c in enumerate(out_comps)}

    for size in sorted(set(c['size'] for c in in_comps + out_comps)):
        if size in size_to_in and size in size_to_out:
            print(f"  Size {size}: input->comp{size_to_in[size]}, output->comp{size_to_out[size]}")

