# Proper component extraction
def get_components(grid):
    visited = set()
    components = []

    def bfs(i, j, color):
        comp = []
        queue = [(i,j)]
        while queue:
            rr, cc = queue.pop(0)
            if (rr, cc) in visited or grid[rr][cc] != color:
                continue
            visited.add((rr, cc))
            comp.append((rr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nn, mm = rr + dr, cc + dc
                if 0 <= nn < len(grid) and 0 <= mm < len(grid[0]):
                    if grid[nn][mm] == color and (nn, mm) not in visited:
                        queue.append((nn, mm))
        return comp

    h, w = len(grid), len(grid[0])
    for i in range(h):
        for j in range(w):
            if grid[i][j] > 0 and (i,j) not in visited:
                color = grid[i][j]
                comp = bfs(i, j, color)
                rows = [r for r,c in comp]
                cols = [c for r,c in comp]
                components.append({
                    'color': color,
                    'cells': comp,
                    'size': len(comp),
                    'rows': rows,
                    'cols': cols,
                    'bbox_rmin': min(rows),
                    'bbox_rmax': max(rows),
                    'bbox_cmin': min(cols),
                    'bbox_cmax': max(cols)
                })

    return components

