G = load()

# Now let me build a prediction function and test it
def predict_output(grid):
    # Extract components
    visited = set()
    h, w = len(grid), len(grid[0])

    def bfs(i, j, color):
        comp = []
        queue = [(i,j)]
        while queue:
            rr, cc = queue.pop(0)
            if (rr, cc) in visited or grid[rr][cc] != color:
                continue
            visited.add((rr, cc))
            comp.append((rr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nn, mm = rr + dr, cc + dc
                if 0 <= nn < h and 0 <= mm < w:
                    if grid[nn][mm] == color and (nn, mm) not in visited:
                        queue.append((nn, mm))
        return comp

    components = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] > 0 and (i,j) not in visited:
                color = grid[i][j]
                comp = bfs(i, j, color)
                components.append({
                    'color': color,
                    'cells': comp,
                    'size': len(comp),
                    'bbox_rmin': min(r for r,c in comp),
                    'bbox_cmin': min(c for r,c in comp),
                    'shape_cells': [(c-rmin+cmin, c-cmax+cmin) for r,c in comp]  # relative coords won't work
                })

    # Group by color and sort by size descending
    by_color = {}
    for c in components:
        by_color.setdefault(c['color'], []).append(c)

    for color in by_color:
        by_color[color].sort(key=lambda x: -x['size'])  # larger sizes first

    # Build output grid
    out_grid = [[0]*w for _ in range(h)]

    # Get sorted colors (ascending = leftmost colors first)
    sorted_colors = sorted(by_color.keys())

    # Assign column band to each color based on its rank
    col_band_width = 4  # Width of each color band

    for col_idx, color in enumerate(sorted_colors):
        col_offset = col_idx * col_band_width

        for comp in by_color[color]:
            # Determine vertical placement
            # First component starts at row 5, then gaps of 2 rows
            row_offset = 5 + (sum(1 for prev in by_color[color][:by_color[color].index(comp)]) * 2)

            # Calculate new positions
            cells = comp['cells']
            min_r = min(r for r,c in cells)
            min_c = min(c for r,c in cells)

            for old_r, old_c in cells:
                new_r = row_offset + (old_r - min_r)
                new_c = col_offset + (old_c - min_c)

                # Clamp to grid bounds
                if 0 <= new_r < h and 0 <= new_c < w:
                    out_grid[new_r][new_c] = color

    return out_grid

