def get_all_components(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    all_comps = []

    for i in range(h):
        for j in range(w):
            if grid[i][j] > 0 and (i,j) not in visited:
                color = grid[i][j]
                comp_cells = []
                queue = [(i,j)]
                while queue:
                    rr, cc = queue.pop(0)
                    if (rr, cc) in visited or grid[rr][cc] != color:
                        continue
                    visited.add((rr, cc))
                    comp_cells.append((rr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nn, mm = rr + dr, cc + dc
                        if 0 <= nn < h and 0 <= mm < w:
                            if grid[nn][mm] == color and (nn, mm) not in visited:
                                queue.append((nn, mm))

                min_r, max_r = min(r for r,c in comp_cells), max(r for r,c in comp_cells)
                min_c, max_c = min(c for r,c in comp_cells), max(c for r,c in comp_cells)
                all_comps.append({
                    'color': color, 'size': len(comp_cells),
                    'cells': comp_cells,
                    'bbox_rmin': min_r, 'bbox_rmax': max_r,
                    'bbox_cmin': min_c, 'bbox_cmax': max_c,
                    'box_w': max_c - min_c + 1,
                    'box_h': max_r - min_r + 1
                })
    return all_comps

